                  { id: "delete-description", className: "supporting" },
                  "This will remove the image from your library. This action can’t be undone."
                )
              )
            ),
            h(
              "div",
              { className: "dialog-actions" },
              closeButton,
              confirmButton
            )
          )
        );
      }

      function ImagePreview() {
        const app = h("main", { className: "app" });
        const dialog = ConfirmDeleteDialog({
          onClose: () => setOpen(false),
          onConfirm: () => {
            setOpen(false);
          },
        });

        const image = h("img", {
          src: "https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1200&q=80",
          alt: "Preview of a photo library image",
        });

        const openButtons = [
          h(
            "button",
            {
              className: "button trigger",
              type: "button",
              onClick: () => setOpen(true),
            },
            "Delete image"
          ),
