            "div",
            { className: "content" },
            h("div", { className: "meta" }, "Library image"),
            h("h1", {}, "Clean, focused image review"),
            h(
              "p",
              {},
              "Review the image before sending it to trash. The delete control is ready when you are."
            ),
            h("div", { className: "actions" }, openButtons)
          )
        );

        app.append(preview, dialog);
        return { app, dialog };
      }

